mapper.select:
SELECT target_id AS targetId , permission AS permission, biz_type AS bizType FROM user_privilege WHERE is_del = 1 AND biz_type = #{bizType}
AND user_id = #{userId}
AND target_id = #{targetId}
UNION SELECT target_id AS targetId , permission AS permission, biz_type AS bizType FROM group_privilege WHERE is_del = 1 AND group_id IN ( SELECT gi.id FROM group_info gi INNER JOIN user_group ug ON gi.id = ug.group_id
AND ug.user_id = #{userId}
) AND biz_type = #{bizType}
AND target_id = #{targetId}
